# /// script
# requires-python = ">=3.13"
# dependencies = [
#     "marimo",
#     "mogs",
# ]
# ///

import marimo

app = marimo.App()

with app.setup:
    import mogs


@app.cell
def _():
    mogs.assignment()
    return


@app.function
def double(x):
    # BEGIN SOLUTION
    return 2 * x
    # END SOLUTION


@app.cell
def _():
    # HIDDEN
    EXPECTED = double(2)
    return (EXPECTED,)


@app.cell
def _(EXPECTED):
    # HIDDEN
    def test_q1_double():
        assert EXPECTED == 4

    return


@app.cell
def _():
    mogs.grade("q1", points=1)
    return


if __name__ == "__main__":
    app.run()

